// Clean-room TSVC s233/s2233 profiles; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const bits=@as(u64,@bitCast(v));for(0..8)|k|out[p+k]=@truncate(bits>>(8*k));}
pub export fn tsvc_s233_s2233_matrix_prefix(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<14 or length>194)return -1;const v=input.?[0..length];const nr=v[0];const mode=v[1];if(nr<2 or nr>8 or (mode!=0 and mode!=1))return -1;const n:usize=@intCast(nr);const nn=n*n;if(length!=2+3*nn)return -1;var a=[_]i64{0}**64;var b=[_]i64{0}**64;var c=[_]i64{0}**64;for(0..nn)|k|{const x=v[2+k];const y=v[2+nn+k];const z=v[2+2*nn+k];if(x< -1 or x>1 or y< -1 or y>1 or z< -1 or z>1)return -1;a[k]=x;b[k]=y;c[k]=z;}if(output==null or capacity<16*nn)return -2;for(1..n)|i|{for(1..n)|j|{a[j*n+i]=a[(j-1)*n+i]+c[j*n+i];}}if(mode==0){for(1..n)|i|{for(1..n)|j|{b[j*n+i]=b[j*n+i-1]+c[j*n+i];}}}else{for(1..n)|i|{for(1..n)|j|{b[i*n+j]=b[(i-1)*n+j]+c[i*n+j];}}}for(0..nn)|k|{put64(output.?,8*k,a[k]);put64(output.?,8*(nn+k),b[k]);}return @intCast(2*nn);}
